        //                     "f": "0.000012500",
        //                     "option_pricing": null,
        //                     "I": "84210.9",
        //                     "M": "84210.2",
        //                     "stats": {
        //                         "c": "16.41",
        //                         "v": "1377350.271",
        //                         "pr": "1377095.872",
        //                         "n": 98,
        //                         "oi": "0",
        //                         "h": "84282",
        //                         "l": "83661.8",
        //                         "p": "0"
        //                     },
        //                     "minp": "82526.1",
        //                     "maxp": "85894.9"
        //                 }
        //             }
        //         }
        //     }
